import type { EnvEnvSchema } from "@saflib/env/env";
import type { NodeEnvSchema } from "@saflib/node/env";
import type { OryKratosHttpEnvSchema } from "@saflib/ory-kratos-http/env";
import type { VendorsSentryNodeEnvSchema } from "@saflib/vendors-sentry-node/env";
import type { RecipesServiceEnvSchema } from "@sderickson/recipes-service/env";
import type { RecipesServiceCommonEnvSchema } from "@sderickson/recipes-service-common/env";

/**
 * Environment variables for the `@sderickson/recipes-monolith` package, including inherited variables via `extends`.
 * Generated by `@saflib/env`. To update, make changes to the adjacent `env.schema.json`, navigate to the package root, and run `npm exec saf-env generate`.
 */
export interface RecipesMonolithEnvSchema
  extends
    EnvEnvSchema,
    NodeEnvSchema,
    OryKratosHttpEnvSchema,
    VendorsSentryNodeEnvSchema,
    RecipesServiceEnvSchema,
    RecipesServiceCommonEnvSchema {}

/**
 * `process.env` casted to the `RecipesMonolithEnvSchema` type.
 */
export const typedEnv = (globalThis.process
  ? process.env
  : {}) as unknown as RecipesMonolithEnvSchema;
